properties.query:
let dcom_events = SecurityEvent | where EventID == 4624 and AuthenticationPackageName == "Negotiate" and ProcessName has_any ("dcom", "rpcss") | summarize dcom_time=min(TimeGenerated) by TargetUserName, Computer;
let shell_events = SecurityEvent | where EventID == 4688 and NewProcessName has_any ("cmd.exe", "powershell.exe", "wscript.exe") | summarize shell_time=min(TimeGenerated) by SubjectUserName, Computer;
let c2_events = NetworkEvents | where RemoteUrl has_any ("pastebin", "github", "cloudflare") or DestinationPort in (4444, 8888, 9999) | summarize c2_time=min(TimeGenerated) by Computer;
dcom_events | join kind=inner shell_events on $left.TargetUserName == $right.SubjectUserName | where shell_time - dcom_time between (0min .. 30min)
